// Package orgclient is a thin wrapper over the org-svc gRPC
// TenantServiceClient. admin-bff uses it from invite handlers to add newly
// provisioned users to the correct tenant.
//
// Transport credentials are decided by the caller via mtls.Config: with
// the three MTLS_*_FILE env vars set, we dial with mTLS; otherwise the
// helper returns insecure credentials (current state — Vault PKI rollout
// is staged).
package orgclient

import (
	"context"

	"github.com/google/uuid"
	"google.golang.org/grpc"
	"google.golang.org/grpc/metadata"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/auth"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/grpcclient"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/mtls"
	feature_flagv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/org/feature_flag/v1"
	integrationv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/org/integration/v1"
	provider_keyv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/org/provider_key/v1"
	tenantv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/org/tenant/v1"
)

// AuthorizationKey is the gRPC metadata key (lowercase) that carries the
// bearer token forwarded from the inbound HTTP request.
const AuthorizationKey = "authorization"

// ContextWithBearerForTenant is like ContextWithBearer but uses the
// supplied tenantID for x-tenant-id instead of the caller's JWT org.
// Required for cross-org admin operations (e.g. platform admin
// inviting a user into a different org): org-svc's RLS gates
// writes by row tenancy, so the GUC must match the membership's tenant_id.
// Authorization is gated upstream (RBAC scope + realm role checks
// at the BFF; JWT aud/azp check at the service hop — mTLS is not enforced
// on that hop: MTLS_*_FILE is unset and OMNICORE_ALLOW_INSECURE_MTLS
// defaults true; #2380 tracks wiring it).
//
// x-user-id and x-actor-type are still populated from the JWT claims so
// audit attribution continues to name the actual caller.
func ContextWithBearerForTenant(ctx context.Context, bearer, tenantID string) context.Context {
	pairs := []string{}
	if bearer != "" {
		pairs = append(pairs, AuthorizationKey, bearer)
	}
	if tenantID != "" {
		pairs = append(pairs, auth.HeaderTenantID, tenantID)
	}
	if c, ok := auth.ClaimsFromContext(ctx); ok {
		if c.Subject != "" {
			pairs = append(pairs, auth.HeaderUserID, c.Subject)
		}
		pairs = append(pairs, auth.HeaderActorType, "user")
	}
	if len(pairs) == 0 {
		return ctx
	}
	return metadata.AppendToOutgoingContext(ctx, pairs...)
}

// ContextWithBearer returns ctx with the inbound HTTP bearer token set as
// the gRPC `authorization` metadata entry, plus the platform x-* headers
// (x-tenant-id, x-user-id, x-actor-type) minted from the validated JWT
// claims attached to ctx by the auth middleware. See identityclient for
// the full rationale.
func ContextWithBearer(ctx context.Context, bearer string) context.Context {
	pairs := []string{}
	if bearer != "" {
		pairs = append(pairs, AuthorizationKey, bearer)
	}
	if c, ok := auth.ClaimsFromContext(ctx); ok {
		if c.OrgID != "" {
			pairs = append(pairs, auth.HeaderTenantID, c.OrgID)
		}
		if c.Subject != "" {
			pairs = append(pairs, auth.HeaderUserID, c.Subject)
		}
		pairs = append(pairs, auth.HeaderActorType, "user")
	}
	if len(pairs) == 0 {
		return ctx
	}
	return metadata.AppendToOutgoingContext(ctx, pairs...)
}

// Client wraps a gRPC connection to org-svc.
type Client struct {
	conn        *grpc.ClientConn
	tenant      tenantv1.TenantServiceClient
	integration integrationv1.IntegrationServiceClient
	featureFlag feature_flagv1.FeatureFlagServiceClient
	providerKey provider_keyv1.ProviderKeyServiceClient
	// Mode reports whether the underlying transport is mTLS or insecure
	// — exposed so callers can log the posture once at startup.
	Mode mtls.Mode
}

// NewClient dials org-svc at addr with the given mTLS posture.
// Pass an empty mtls.Config{} to get insecure transport (current dev
// default); set CertFile/KeyFile/CAFile to dial with mTLS. Partial
// configuration is a hard error.
func NewClient(addr string, mtlsCfg mtls.Config) (*Client, error) {
	creds, mode, err := mtls.BuildTransportCredentials(mtlsCfg)
	if err != nil {
		return nil, err
	}
	// P0-05: fail closed instead of silently dialing plaintext.
	if err := mtls.EnforceMode(mode); err != nil {
		return nil, err
	}
	conn, err := grpc.NewClient(addr, grpcclient.DialOptions(grpcclient.TierFast, grpc.WithTransportCredentials(creds))...)
	if err != nil {
		return nil, err
	}
	return NewClientFromConn(conn, mode)
}

// NewClientFromConn builds a Client from an already-dialled *grpc.ClientConn.
// This constructor is used by tests that inject an in-process bufconn
// connection. Mode must match the transport used by the caller.
func NewClientFromConn(conn *grpc.ClientConn, mode mtls.Mode) (*Client, error) {
	return &Client{
		conn:        conn,
		tenant:      tenantv1.NewTenantServiceClient(conn),
		integration: integrationv1.NewIntegrationServiceClient(conn),
		featureFlag: feature_flagv1.NewFeatureFlagServiceClient(conn),
		providerKey: provider_keyv1.NewProviderKeyServiceClient(conn),
		Mode:        mode,
	}, nil
}

// GetEmailIntegration fetches the org-level email integration row.
// Returns (nil, nil) when `present=false` — the admin-mfe renders an
// empty form in that case.
func (c *Client) GetEmailIntegration(
	ctx context.Context, bearer, orgID string,
) (*integrationv1.EmailIntegration, error) {
	ctx = ContextWithBearerForTenant(ctx, bearer, orgID)
	resp, err := c.integration.GetEmailIntegration(ctx, &integrationv1.GetEmailIntegrationRequest{
		OrgId: orgID,
	})
	if err != nil {
		return nil, err
	}
	if !resp.GetPresent() {
		return nil, nil
	}
	return resp.GetIntegration(), nil
}

// UpdateEmailIntegrationParams carries every field the upstream RPC
// accepts. The bff handler builds this from the JSON request body.
type UpdateEmailIntegrationParams struct {
	OrgID string

	SMTPHost, SMTPUsername, SMTPFromAddress, SMTPPassword string
	SMTPPort                                              int32
	SMTPUseTLS                                            bool

	IMAPHost, IMAPUsername, IMAPFolder, IMAPPassword string
	IMAPPort                                         int32
	IMAPUseSSL                                       bool
}

// UpdateEmailIntegration upserts the org's integration row. Empty
// passwords are preserved by the server (no overwrite of existing
// Vault refs).
func (c *Client) UpdateEmailIntegration(
	ctx context.Context, bearer string, p UpdateEmailIntegrationParams,
) (*integrationv1.EmailIntegration, error) {
	ctx = ContextWithBearerForTenant(ctx, bearer, p.OrgID)
	resp, err := c.integration.UpdateEmailIntegration(ctx, &integrationv1.UpdateEmailIntegrationRequest{
		OrgId:           p.OrgID,
		SmtpHost:        p.SMTPHost,
		SmtpPort:        p.SMTPPort,
		SmtpUsername:    p.SMTPUsername,
		SmtpUseTls:      p.SMTPUseTLS,
		SmtpFromAddress: p.SMTPFromAddress,
		SmtpPassword:    p.SMTPPassword,
		ImapHost:        p.IMAPHost,
		ImapPort:        p.IMAPPort,
		ImapUsername:    p.IMAPUsername,
		ImapUseSsl:      p.IMAPUseSSL,
		ImapFolder:      p.IMAPFolder,
		ImapPassword:    p.IMAPPassword,
	})
	if err != nil {
		return nil, err
	}
	return resp.GetIntegration(), nil
}

// Close releases the underlying gRPC connection.
func (c *Client) Close() error {
	return c.conn.Close()
}

// AddMember adds a user to the given tenant with the specified role.
// tenantID is the UUIDv7 of the org-svc tenant; userID is the UUIDv7 of the
// identity-svc user.
func (c *Client) AddMember(ctx context.Context, tenantID, userID uuid.UUID, role tenantv1.MembershipRole) (*tenantv1.Membership, error) {
	resp, err := c.tenant.AddMember(ctx, &tenantv1.AddMemberRequest{
		TenantId: tenantID.String(),
		UserId:   userID.String(),
		Role:     role,
	})
	if err != nil {
		return nil, err
	}
	return resp.GetMembership(), nil
}

// ListMembershipsByUser returns every membership the given user holds in
// the caller's org tree, with the tenant name + slug already joined for
// display. RLS at org-svc scopes the result; an empty slice is the
// legitimate "no memberships visible" answer.
func (c *Client) ListMembershipsByUser(ctx context.Context, userID uuid.UUID) ([]*tenantv1.MembershipWithTenant, error) {
	resp, err := c.tenant.ListMembershipsByUser(ctx, &tenantv1.ListMembershipsByUserRequest{
		UserId: userID.String(),
	})
	if err != nil {
		return nil, err
	}
	return resp.GetMemberships(), nil
}

// ListTenantsParams carries the pagination + filter parameters.
type ListTenantsParams struct {
	// ParentID filters to children of this tenant. Empty string means
	// "root tenants only" (matches org-svc's IS NOT DISTINCT FROM NULL).
	// Nil means "no parent filter".
	ParentID  *string
	PageSize  uint32
	PageToken string
}

// ListTenantsResult mirrors the gRPC ListResponse: the page of tenants +
// next token (empty when no more pages exist).
type ListTenantsResult struct {
	Tenants       []*tenantv1.Tenant
	NextPageToken string
}

// BootstrapTenantParams carries the inputs for the create flow. ParentID
// nil = new root tenant; a UUID string = child of that parent.
// TrialDays > 0 sets a trial expiry at insert time; the server caps at 365.
type BootstrapTenantParams struct {
	Name      string
	Slug      string
	ParentID  *string
	DryRun    bool
	TrialDays uint32
}

// BootstrapTenantResult mirrors the gRPC response so admin-mfe can show
// "would create this tenant" on dry-run without unwrapping the proto.
type BootstrapTenantResult struct {
	Tenant        *tenantv1.Tenant
	DryRunPlanned bool
}

// BootstrapTenant creates a new tenant via org-svc. Admin-driven; legacy_id-
// bearing creates remain migrator-only and aren't exposed here.
func (c *Client) BootstrapTenant(ctx context.Context, p BootstrapTenantParams) (*BootstrapTenantResult, error) {
	req := &tenantv1.BootstrapRequest{
		Name:      p.Name,
		Slug:      p.Slug,
		DryRun:    p.DryRun,
		TrialDays: p.TrialDays,
	}
	if p.ParentID != nil {
		v := *p.ParentID
		req.ParentId = &v
	}
	resp, err := c.tenant.Bootstrap(ctx, req)
	if err != nil {
		return nil, err
	}
	return &BootstrapTenantResult{
		Tenant:        resp.GetTenant(),
		DryRunPlanned: resp.GetDryRunPlanned(),
	}, nil
}

// DeleteTenant soft-deletes a tenant via org-svc Delete. Returns the
// post-image so admin-mfe can show the updated status. Phase 4f.
func (c *Client) DeleteTenant(ctx context.Context, tenantID string) (*tenantv1.Tenant, error) {
	resp, err := c.tenant.Delete(ctx, &tenantv1.DeleteRequest{TenantId: tenantID})
	if err != nil {
		return nil, err
	}
	return resp.GetTenant(), nil
}

// ActivateTenant flips a suspended workspace back to active via
// org-svc Activate. Returns the post-image. Phase 4g.
func (c *Client) ActivateTenant(ctx context.Context, tenantID string) (*tenantv1.Tenant, error) {
	resp, err := c.tenant.Activate(ctx, &tenantv1.ActivateRequest{TenantId: tenantID})
	if err != nil {
		return nil, err
	}
	return resp.GetTenant(), nil
}

// UpdateTenantStatusParams carries the inputs for the Phase 4i
// UpdateStatus RPC. TargetStatus must be ACTIVE / TRIAL / SUSPENDED;
// PAST_DUE is rejected server-side. TrialDays is required when
// TargetStatus is TRIAL.
type UpdateTenantStatusParams struct {
	TenantID     string
	TargetStatus tenantv1.TenantStatus
	TrialDays    uint32
}

// UpdateTenantStatus drives the admin-mfe status dropdown via the
// org-svc UpdateStatus RPC. Phase 4i.
func (c *Client) UpdateTenantStatus(ctx context.Context, p UpdateTenantStatusParams) (*tenantv1.Tenant, error) {
	resp, err := c.tenant.UpdateStatus(ctx, &tenantv1.UpdateStatusRequest{
		TenantId:     p.TenantID,
		TargetStatus: p.TargetStatus,
		TrialDays:    p.TrialDays,
	})
	if err != nil {
		return nil, err
	}
	return resp.GetTenant(), nil
}

// ListMembershipsByTenant returns the membership roster of one workspace
// (org-svc ListMembershipsByTenant). RLS at org-svc scopes results to the
// caller's org. Phase 4g.
func (c *Client) ListMembershipsByTenant(ctx context.Context, tenantID string) ([]*tenantv1.Membership, error) {
	resp, err := c.tenant.ListMembershipsByTenant(ctx, &tenantv1.ListMembershipsByTenantRequest{
		TenantId: tenantID,
	})
	if err != nil {
		return nil, err
	}
	return resp.GetMemberships(), nil
}

// AddMemberByID is the params-based variant of AddMember used by the
// workspace-detail-route handler so the role string can flow through
// the REST layer without exposing the proto enum. Phase 4g.
type AddMemberByIDParams struct {
	TenantID string
	UserID   string
	Role     tenantv1.MembershipRole
}

// AddMemberByID forwards an admin-bff REST AddMember call to org-svc.
// Phase 4g — separate from AddMember (uuid.UUID) so the REST handler
// can pass through string ids without parsing them twice.
func (c *Client) AddMemberByID(ctx context.Context, p AddMemberByIDParams) (*tenantv1.Membership, error) {
	resp, err := c.tenant.AddMember(ctx, &tenantv1.AddMemberRequest{
		TenantId: p.TenantID,
		UserId:   p.UserID,
		Role:     p.Role,
	})
	if err != nil {
		return nil, err
	}
	return resp.GetMembership(), nil
}

// RemoveMember deletes one (tenant_id, user_id) row via org-svc
// RemoveMember. Phase 4g.
func (c *Client) RemoveMember(ctx context.Context, tenantID, userID string) error {
	_, err := c.tenant.RemoveMember(ctx, &tenantv1.RemoveMemberRequest{
		TenantId: tenantID,
		UserId:   userID,
	})
	return err
}

// RemoveUserFromOrg removes a user from an entire org tree (the org-root
// tenant plus every workspace under it) via org-svc RemoveUserFromOrg.
// orgID is the root tenant UUID; userID is the Keycloak sub. Returns the
// count of org.memberships rows deleted (0 on an idempotent re-run) for
// observability. org-svc owns the owner/admin + self + last-owner gates;
// this wrapper is a thin pass-through and surfaces the gRPC error
// verbatim so the handler can translate it (FailedPrecondition → 409,
// PermissionDenied → 403, …).
func (c *Client) RemoveUserFromOrg(ctx context.Context, orgID, userID string) (uint32, error) {
	resp, err := c.tenant.RemoveUserFromOrg(ctx, &tenantv1.RemoveUserFromOrgRequest{
		OrgId:  orgID,
		UserId: userID,
	})
	if err != nil {
		return 0, err
	}
	return resp.GetMembershipsRemoved(), nil
}

// CheckUserRemovable reports whether removing userID from orgID would trip
// org-svc's last-owner guard. Mutates nothing. Signature mirrors the sibling
// RemoveUserFromOrg wrapper below (orgID, userID) so the pre-flight and the
// write are called identically. The caller still pins x-tenant-id via
// ContextWithBearerForTenant because org-svc's RLS GUC needs it.
func (c *Client) CheckUserRemovable(ctx context.Context, orgID, userID string) (bool, error) {
	resp, err := c.tenant.CheckUserRemovable(ctx, &tenantv1.CheckUserRemovableRequest{
		OrgId:  orgID,
		UserId: userID,
	})
	if err != nil {
		return false, err
	}
	return resp.GetIsSoleOwner(), nil
}

// GetTenant fetches a single tenant by id. RLS at org-svc scopes the
// lookup; unknown / cross-tenant ids return a NotFound gRPC error which
// the handler maps to HTTP 404.
func (c *Client) GetTenant(ctx context.Context, tenantID string) (*tenantv1.Tenant, error) {
	resp, err := c.tenant.Get(ctx, &tenantv1.GetRequest{TenantId: tenantID})
	if err != nil {
		return nil, err
	}
	return resp.GetTenant(), nil
}

// UpdateTenantParams carries the editable fields. Empty strings are
// sentinels for "do not change" (matches the org-svc query semantics).
// Studio flag fields follow presence-bit conventions (Sub-PR A1):
// ClearDisabledStudioTools=true or a non-empty DisabledStudioTools list
// triggers the list replacement; OfflineMode is applied when non-nil.
type UpdateTenantParams struct {
	TenantID string
	Name     string
	Slug     string
	// Studio flags — Sub-PR A1.
	DisabledStudioTools      []string
	ClearDisabledStudioTools bool
	// OfflineMode is a pointer so nil means "do not change"; non-nil means apply.
	OfflineMode *bool
}

// UpdateTenant mutates name/slug/studio-flags on an existing tenant and returns
// the post-image. RLS at org-svc scopes the write; cross-tenant writes
// surface as NotFound.
func (c *Client) UpdateTenant(ctx context.Context, p UpdateTenantParams) (*tenantv1.Tenant, error) {
	req := &tenantv1.UpdateRequest{
		TenantId:                 p.TenantID,
		Name:                     p.Name,
		Slug:                     p.Slug,
		DisabledStudioTools:      p.DisabledStudioTools,
		ClearDisabledStudioTools: p.ClearDisabledStudioTools,
	}
	if p.OfflineMode != nil {
		req.OfflineMode = *p.OfflineMode
		req.SetOfflineMode = true
	}
	resp, err := c.tenant.Update(ctx, req)
	if err != nil {
		return nil, err
	}
	return resp.GetTenant(), nil
}

// ListTenants pages through tenants in the caller's org tree. RLS at
// org-svc scopes the result by app.current_org_id.
func (c *Client) ListTenants(ctx context.Context, p ListTenantsParams) (*ListTenantsResult, error) {
	req := &tenantv1.ListRequest{
		PageSize:  p.PageSize,
		PageToken: p.PageToken,
	}
	if p.ParentID != nil {
		v := *p.ParentID
		req.ParentId = &v
	}
	resp, err := c.tenant.List(ctx, req)
	if err != nil {
		return nil, err
	}
	return &ListTenantsResult{
		Tenants:       resp.GetTenants(),
		NextPageToken: resp.GetNextPageToken(),
	}, nil
}

// UpdateMembershipRoleParams carries the inputs for the Phase 4j
// inline role-change path.
type UpdateMembershipRoleParams struct {
	TenantID string
	UserID   string
	Role     tenantv1.MembershipRole
}

// UpdateMembershipRole forwards to org-svc UpdateMembershipRole RPC.
// Phase 4j.
func (c *Client) UpdateMembershipRole(
	ctx context.Context, p UpdateMembershipRoleParams,
) (*tenantv1.Membership, error) {
	resp, err := c.tenant.UpdateMembershipRole(ctx, &tenantv1.UpdateMembershipRoleRequest{
		TenantId: p.TenantID,
		UserId:   p.UserID,
		Role:     p.Role,
	})
	if err != nil {
		return nil, err
	}
	return resp.GetMembership(), nil
}

// CountMembershipsByUsers forwards to org-svc; empty input
// short-circuits with an empty map. Phase 4j.
func (c *Client) CountMembershipsByUsers(
	ctx context.Context, userIDs []string,
) (map[string]uint32, error) {
	if len(userIDs) == 0 {
		return map[string]uint32{}, nil
	}
	resp, err := c.tenant.CountMembershipsByUsers(ctx, &tenantv1.CountMembershipsByUsersRequest{
		UserIds: userIDs,
	})
	if err != nil {
		return nil, err
	}
	return resp.GetCounts(), nil
}

// ListFeatureFlags returns the effective enabled state for every known
// vertical key from org-svc. The feature-flag table carries no RLS, but the
// outbox path inside org-svc requires a non-zero tenant GUC, so the caller
// must pre-wire the bearer and the admin's own OrgID (as x-tenant-id) into
// ctx via ContextWithBearerForTenant before calling this method.
func (c *Client) ListFeatureFlags(
	ctx context.Context,
) ([]*feature_flagv1.FeatureFlag, error) {
	resp, err := c.featureFlag.ListFeatureFlags(ctx, &feature_flagv1.ListFeatureFlagsRequest{})
	if err != nil {
		return nil, err
	}
	return resp.GetFlags(), nil
}

// SetFeatureFlag upserts a platform-global feature flag via org-svc.
// key must be one of the nine known vertical identifiers (dialogue, range,
// spaces, studio, ask, workflows, clio, files, monitor); org-svc returns
// INVALID_ARGUMENT for unknown keys, which the BFF handler translates to
// HTTP 400.
// The caller must pre-wire the bearer and the admin's own OrgID (as
// x-tenant-id) into ctx via ContextWithBearerForTenant before calling this
// method — the outbox write inside org-svc's SetFeatureFlag requires a
// non-zero tenant GUC even though the flag table itself is tenant-free.
func (c *Client) SetFeatureFlag(
	ctx context.Context, key string, enabled bool,
) (*feature_flagv1.FeatureFlag, error) {
	resp, err := c.featureFlag.SetFeatureFlag(ctx, &feature_flagv1.SetFeatureFlagRequest{
		Key:     key,
		Enabled: enabled,
	})
	if err != nil {
		return nil, err
	}
	return resp.GetFlag(), nil
}

// ListProviderKeys returns presence/metadata for every platform provider key
// (Serper / Apify / Jina) from org-svc. The response NEVER carries the raw
// secret — only the Vault path reference and configured/updated metadata. The
// provider-key table carries no RLS, but org-svc's outbox path requires a
// non-zero tenant GUC, so the caller must pre-wire the bearer and the admin's
// own OrgID (as x-tenant-id) into ctx via ContextWithBearerForTenant before
// calling this method — matching the feature-flag convention.
func (c *Client) ListProviderKeys(
	ctx context.Context,
) ([]*provider_keyv1.ProviderKey, error) {
	resp, err := c.providerKey.ListProviderKeys(ctx, &provider_keyv1.ListProviderKeysRequest{})
	if err != nil {
		return nil, err
	}
	return resp.GetKeys(), nil
}

// SetProviderKey stores one provider's shared API key via org-svc, returning
// the post-image metadata (never the raw secret). provider is the canonical
// slug (serper / apify / jina); an unrecognised slug maps to
// PROVIDER_UNSPECIFIED, which org-svc rejects with INVALID_ARGUMENT — the BFF
// handler translates that to HTTP 400. An empty apiKey means "leave the
// existing Vault ref untouched" (mirrors integration secret handling).
//
// The caller must pre-wire the bearer and the admin's own OrgID (as
// x-tenant-id) into ctx via ContextWithBearerForTenant before calling this
// method — the outbox write inside org-svc's SetProviderKey requires a
// non-zero tenant GUC even though the provider-key table itself is tenant-free.
func (c *Client) SetProviderKey(
	ctx context.Context, provider, apiKey string,
) (*provider_keyv1.ProviderKey, error) {
	resp, err := c.providerKey.SetProviderKey(ctx, &provider_keyv1.SetProviderKeyRequest{
		Provider: ProviderSlugToProto(provider),
		ApiKey:   apiKey,
	})
	if err != nil {
		return nil, err
	}
	return resp.GetKey(), nil
}

// providerSlugByEnum is the single source of truth mapping the wire enum to the
// canonical provider slug WITHIN the admin-bff module. Both directions
// (ProviderSlugToProto / ProviderProtoToSlug) derive from it, and the
// handlers package reuses these helpers rather than keeping a second table, so
// a provider rename can never drift between the two packages.
var providerSlugByEnum = map[provider_keyv1.Provider]string{
	provider_keyv1.Provider_PROVIDER_SERPER: "serper",
	provider_keyv1.Provider_PROVIDER_APIFY:  "apify",
	provider_keyv1.Provider_PROVIDER_JINA:   "jina",
}

// ProviderSlugToProto maps a canonical provider slug to the wire enum. An
// unrecognised slug maps to PROVIDER_UNSPECIFIED so org-svc can reject it with
// a single, consistent INVALID_ARGUMENT rather than the BFF guessing.
func ProviderSlugToProto(provider string) provider_keyv1.Provider {
	for enum, slug := range providerSlugByEnum {
		if slug == provider {
			return enum
		}
	}
	return provider_keyv1.Provider_PROVIDER_UNSPECIFIED
}

// ProviderProtoToSlug is the inverse: it maps the wire enum to the canonical
// provider slug. PROVIDER_UNSPECIFIED and any unrecognised value render as ""
// so the HTTP wire contract never leaks an internal enum name.
func ProviderProtoToSlug(p provider_keyv1.Provider) string {
	return providerSlugByEnum[p]
}


