// Package orgclient is a thin wrapper over the org-svc gRPC
// TenantServiceClient. admin-bff uses it from invite handlers to add newly
// provisioned users to the correct tenant.
//
// Transport credentials are decided by the caller via mtls.Config: with
// the three MTLS_*_FILE env vars set, we dial with mTLS; otherwise the
// helper returns insecure credentials (current state — Vault PKI rollout
// is staged).
package orgclient

import (
	"context"

	"github.com/google/uuid"
	"google.golang.org/grpc"
	"google.golang.org/grpc/metadata"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/auth"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/grpcclient"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/mtls"
	feature_flagv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/org/feature_flag/v1"
	integrationv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/org/integration/v1"
	provider_keyv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/org/provider_key/v1"
	tenantv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/org/tenant/v1"
)

// AuthorizationKey is the gRPC metadata key (lowercase) that carries the
// bearer token forwarded from the inbound HTTP request.
const AuthorizationKey = "authorization"

// ContextWithBearerForTenant is like ContextWithBearer but uses the
// supplied tenantID for x-tenant-id instead of the caller's JWT org.
// Required for cross-org admin operations (e.g. platform admin
// inviting a user into a different org): org-svc's RLS gates
// writes by row tenancy, so the GUC must match the membership's tenant_id.
// Authorization is gated upstream (RBAC scope + realm role checks
// at the BFF; JWT aud/azp check at the service hop — mTLS is not enforced
// on that hop: MTLS_*_FILE is unset and OMNICORE_ALLOW_INSECURE_MTLS
// defaults true; #2380 tracks wiring it).
//
// x-user-id and x-actor-type are still populated from the JWT claims so
// audit attribution continues to name the actual caller.
func ContextWithBearerForTenant(ctx context.Context, bearer, tenantID string) context.Context {
	pairs := []string{}
	if bearer != "" {
		pairs = append(pairs, AuthorizationKey, bearer)
	}
	if tenantID != "" {
		pairs = append(pairs, auth.HeaderTenantID, tenantID)
	}
	if c, ok := auth.ClaimsFromContext(ctx); ok {
		if c.Subject != "" {
			pairs = append(pairs, auth.HeaderUserID, c.Subject)
		}
		pairs = append(pairs, auth.HeaderActorType, "user")
	}
	if len(pairs) == 0 {
		return ctx
	}
	return metadata.AppendToOutgoingContext(ctx, pairs...)
}

// ContextWithBearer returns ctx with the inbound HTTP bearer token set as
// the gRPC `authorization` metadata entry, plus the platform x-* headers
// (x-tenant-id, x-user-id, x-actor-type) minted from the validated JWT
// claims attached to ctx by the auth middleware. See identityclient for
// the full rationale.
func ContextWithBearer(ctx context.Context, bearer string) context.Context {
	pairs := []string{}
	if bearer != "" {
		pairs = append(pairs, AuthorizationKey, bearer)
	}
	if c, ok := auth.ClaimsFromContext(ctx); ok {
		if c.OrgID != "" {
			pairs = append(pairs, auth.HeaderTenantID, c.OrgID)
		}
		if c.Subject != "" {
			pairs = append(pairs, auth.HeaderUserID, c.Subject)
		}
		pairs = append(pairs, auth.HeaderActorType, "user")
	}
	if len(pairs) == 0 {
		return ctx
	}
	return metadata.AppendToOutgoingContext(ctx, pairs...)
}

// Client wraps a gRPC connection to org-svc.
type Client struct {
	conn        *grpc.ClientConn
	tenant      tenantv1.TenantServiceClient
	integration integrationv1.IntegrationServiceClient
	featureFlag feature_flagv1.FeatureFlagServiceClient
	providerKey provider_keyv1.ProviderKeyServiceClient
	// Mode reports whether the underlying transport is mTLS or insecure
	// — exposed so callers can log the posture once at startup.
	Mode mtls.Mode
}

// NewClient dials org-svc at addr with the given mTLS posture.
// Pass an empty mtls.Config{} to get insecure transport (current dev
// default); set CertFile/KeyFile/CAFile to dial with mTLS. Partial
// configuration is a hard error.
func NewClient(addr string, mtlsCfg mtls.Config) (*Client, error) {
	creds, mode, err := mtls.BuildTransportCredentials(mtlsCfg)
	if err != nil {
		return nil, err
	}
	// P0-05: fail closed instead of silently dialing plaintext.
	if err := mtls.EnforceMode(mode); err != nil {
		return nil, err
	}
	conn, err := grpc.NewClient(addr, grpcclient.DialOptions(grpcclient.TierFast, grpc.WithTransportCredentials(creds))...)
	if err != nil {
		return nil, err
	}
	return NewClientFromConn(conn, mode)
}

// NewClientFromConn builds a Client from an already-dialled *grpc.ClientConn.
// This constructor is used by tests that inject an in-process bufconn
// connection. Mode must match the transport used by the caller.
func NewClientFromConn(conn *grpc.ClientConn, mode mtls.Mode) (*Client, error) {
	return &Client{
		conn:        conn,
		tenant:      tenantv1.NewTenantServiceClient(conn),
		integration: integrationv1.NewIntegrationServiceClient(conn),
		featureFlag: feature_flagv1.NewFeatureFlagServiceClient(conn),
		providerKey: provider_keyv1.NewProviderKeyServiceClient(conn),
		Mode:        mode,
	}, nil
}

// GetEmailIntegration fetches the org-level email integration row.
// Returns (nil, nil) when `present=false` — the admin-mfe renders an
// empty form in that case.
func (c *Client) GetEmailIntegration(
	ctx context.Context, bearer, orgID string,
) (*integrationv1.EmailIntegration, error) {
	ctx = ContextWithBearerForTenant(ctx, bearer, orgID)
	resp, err := c.integration.GetEmailIntegration(ctx, &integrationv1.GetEmailIntegrationRequest{
		OrgId: orgID,
	})
	if err != nil {
		return nil, err
	}
	if !resp.GetPresent() {
		return nil, nil
	}
	return resp.GetIntegration(), nil
}

// UpdateEmailIntegrationParams carries every field the upstream RPC
// accepts. The bff handler builds this from the JSON request body.
type UpdateEmailIntegrationParams struct {
	OrgID string

	SMTPHost, SMTPUsername, SMTPFromAddress, SMTPPassword string
	SMTPPort                                              int32
	SMTPUseTLS                                            bool

	IMAPHost, IMAPUsername, IMAPFolder, IMAPPassword string
	IMAPPort                                         int32
	IMAPUseSSL                                       bool
}

// UpdateEmailIntegration upserts the org's integration row. Empty
// passwords are preserved by the server (no overwrite of existing
// Vault refs).
func (c *Client) UpdateEmailIntegration(
	ctx context.Context, bearer string, p UpdateEmailIntegrationParams,
) (*integrationv1.EmailIntegration, error) {
	ctx = ContextWithBearerForTenant(ctx, bearer, p.OrgID)
	resp, err := c.integration.UpdateEmailIntegration(ctx, &integrationv1.UpdateEmailIntegrationRequest{
		OrgId:           p.OrgID,
		SmtpHost:        p.SMTPHost,
		SmtpPort:        p.SMTPPort,
		SmtpUsername:    p.SMTPUsername,
		SmtpUseTls:      p.SMTPUseTLS,
		SmtpFromAddress: p.SMTPFromAddress,
		SmtpPassword:    p.SMTPPassword,
		ImapHost:        p.IMAPHost,
		ImapPort:        p.IMAPPort,
		ImapUsername:    p.IMAPUsername,
		ImapUseSsl:      p.IMAPUseSSL,
		ImapFolder:      p.IMAPFolder,
		ImapPassword:    p.IMAPPassword,
	})
	if err != nil {
		return nil, err
	}
	return resp.GetIntegration(), nil
}

// Close releases the underlying gRPC connection.
func (c *Client) Close() error {
