// BootstrapTenantParams carries the inputs for the create flow. ParentID
// nil = new root tenant; a UUID string = child of that parent.
// TrialDays > 0 sets a trial expiry at insert time; the server caps at 365.
type BootstrapTenantParams struct {
	Name      string
	Slug      string
	ParentID  *string
	DryRun    bool
	TrialDays uint32
}

// BootstrapTenantResult mirrors the gRPC response so admin-mfe can show
// "would create this tenant" on dry-run without unwrapping the proto.
type BootstrapTenantResult struct {
	Tenant        *tenantv1.Tenant
	DryRunPlanned bool
}

// BootstrapTenant creates a new tenant via org-svc. Admin-driven; legacy_id-
// bearing creates remain migrator-only and aren't exposed here.
func (c *Client) BootstrapTenant(ctx context.Context, p BootstrapTenantParams) (*BootstrapTenantResult, error) {
	req := &tenantv1.BootstrapRequest{
		Name:      p.Name,
		Slug:      p.Slug,
		DryRun:    p.DryRun,
		TrialDays: p.TrialDays,
	}
	if p.ParentID != nil {
		v := *p.ParentID
		req.ParentId = &v
	}
	resp, err := c.tenant.Bootstrap(ctx, req)
	if err != nil {
		return nil, err
	}
	return &BootstrapTenantResult{
		Tenant:        resp.GetTenant(),
		DryRunPlanned: resp.GetDryRunPlanned(),
	}, nil
}

