// RemoveUserFromOrg removes a user from an entire org tree (the org-root
// tenant plus every workspace under it) via org-svc RemoveUserFromOrg.
// orgID is the root tenant UUID; userID is the Keycloak sub. Returns the
// count of org.memberships rows deleted (0 on an idempotent re-run) for
// observability. org-svc owns the owner/admin + self + last-owner gates;
// this wrapper is a thin pass-through and surfaces the gRPC error
// verbatim so the handler can translate it (FailedPrecondition → 409,
// PermissionDenied → 403, …).
func (c *Client) RemoveUserFromOrg(ctx context.Context, orgID, userID string) (uint32, error) {
	resp, err := c.tenant.RemoveUserFromOrg(ctx, &tenantv1.RemoveUserFromOrgRequest{
		OrgId:  orgID,
		UserId: userID,
	})
	if err != nil {
		return 0, err
	}
	return resp.GetMembershipsRemoved(), nil
}

