// UpdateTenantParams carries the editable fields. Empty strings are
// sentinels for "do not change" (matches the org-svc query semantics).
// Studio flag fields follow presence-bit conventions (Sub-PR A1):
// ClearDisabledStudioTools=true or a non-empty DisabledStudioTools list
// triggers the list replacement; OfflineMode is applied when non-nil.
type UpdateTenantParams struct {
	TenantID string
	Name     string
	Slug     string
	// Studio flags — Sub-PR A1.
	DisabledStudioTools      []string
	ClearDisabledStudioTools bool
	// OfflineMode is a pointer so nil means "do not change"; non-nil means apply.
	OfflineMode *bool
}

// UpdateTenant mutates name/slug/studio-flags on an existing tenant and returns
// the post-image. RLS at org-svc scopes the write; cross-tenant writes
// surface as NotFound.
func (c *Client) UpdateTenant(ctx context.Context, p UpdateTenantParams) (*tenantv1.Tenant, error) {
	req := &tenantv1.UpdateRequest{
		TenantId:                 p.TenantID,
		Name:                     p.Name,
		Slug:                     p.Slug,
		DisabledStudioTools:      p.DisabledStudioTools,
		ClearDisabledStudioTools: p.ClearDisabledStudioTools,
	}
	if p.OfflineMode != nil {
		req.OfflineMode = *p.OfflineMode
		req.SetOfflineMode = true
	}
	resp, err := c.tenant.Update(ctx, req)
	if err != nil {
		return nil, err
	}
	return resp.GetTenant(), nil
}

// ListTenants pages through tenants in the caller's org tree. RLS at
