// SetProviderKey stores one provider's shared API key via org-svc, returning
// the post-image metadata (never the raw secret). provider is the canonical
// slug (serper / apify / jina); an unrecognised slug maps to
// PROVIDER_UNSPECIFIED, which org-svc rejects with INVALID_ARGUMENT — the BFF
// handler translates that to HTTP 400. An empty apiKey means "leave the
// existing Vault ref untouched" (mirrors integration secret handling).
//
// The caller must pre-wire the bearer and the admin's own OrgID (as
// x-tenant-id) into ctx via ContextWithBearerForTenant before calling this
// method — the outbox write inside org-svc's SetProviderKey requires a
// non-zero tenant GUC even though the provider-key table itself is tenant-free.
func (c *Client) SetProviderKey(
	ctx context.Context, provider, apiKey string,
) (*provider_keyv1.ProviderKey, error) {
	resp, err := c.providerKey.SetProviderKey(ctx, &provider_keyv1.SetProviderKeyRequest{
		Provider: ProviderSlugToProto(provider),
		ApiKey:   apiKey,
	})
	if err != nil {
		return nil, err
	}
	return resp.GetKey(), nil
}

// providerSlugByEnum is the single source of truth mapping the wire enum to the
// canonical provider slug WITHIN the admin-bff module. Both directions
// (ProviderSlugToProto / ProviderProtoToSlug) derive from it, and the
// handlers package reuses these helpers rather than keeping a second table, so
// a provider rename can never drift between the two packages.
var providerSlugByEnum = map[provider_keyv1.Provider]string{
	provider_keyv1.Provider_PROVIDER_SERPER: "serper",
	provider_keyv1.Provider_PROVIDER_APIFY:  "apify",
	provider_keyv1.Provider_PROVIDER_JINA:   "jina",
}

// ProviderSlugToProto maps a canonical provider slug to the wire enum. An
// unrecognised slug maps to PROVIDER_UNSPECIFIED so org-svc can reject it with
// a single, consistent INVALID_ARGUMENT rather than the BFF guessing.
func ProviderSlugToProto(provider string) provider_keyv1.Provider {
	for enum, slug := range providerSlugByEnum {
		if slug == provider {
			return enum
		}
	}
	return provider_keyv1.Provider_PROVIDER_UNSPECIFIED
}

// ProviderProtoToSlug is the inverse: it maps the wire enum to the canonical
// provider slug. PROVIDER_UNSPECIFIED and any unrecognised value render as ""
// so the HTTP wire contract never leaks an internal enum name.
func ProviderProtoToSlug(p provider_keyv1.Provider) string {
	return providerSlugByEnum[p]
